public class ChatService {
  private final MembershipStore acl;
  private final DedupStore dedup;
  private final LogPublisher log;
  private final RateLimiter limiter;

  public SendResult send(SendRequest r) {
    if (!limiter.tryAcquire(r.senderId())) return SendResult.rateLimited();
    if (r.body() == null || r.body().length() == 0 || r.body().length() > 8000)
      return SendResult.rejected("bad-body");
    if (!acl.isMember(r.channelId(), r.senderId()))
      return SendResult.rejected("not-member");
    // Exactly-once effect on at-least-once transport.
    String serverId = dedup.getOrCreate(r.senderId(), r.clientMsgId());
    long now = System.currentTimeMillis();
    MessageEvent e = new MessageEvent(r.channelId(), serverId, r.senderId(), r.body(), now, r.parentId());
    log.append(r.channelId(), e); // partitioned by channelId
    return SendResult.acked(serverId, now);
  }

  public Page<Message> history(String channelId, String caller, Cursor cursor, int limit) {
    if (!acl.canRead(channelId, caller)) throw new ForbiddenException();
    return MessageStore.slice(channelId, cursor, Math.min(limit, 50));
  }
}

def on_log_event(event):
    # 1. Durable write first, idempotent on clientMsgId
    inserted = message_store.insert_if_absent(event)
    if not inserted:
        return  # retry duplicate, do not fan out twice
    tail_cache.prepend(event.channel_id, event)
    search_queue.offer(event)  # async, lag is acceptable
    # 2. Fan out only to online devices
    routes = routing_cache.get_routes(event.channel_id)  # user -> [(device, gateway)]
    for user_id, devices in routes.items():
        if user_id == event.sender_id:
            continue  # sender already optimistic-acked, sync others
        for device, gateway in devices:
            if gateway.is_mine():
                push_to_socket(device, event)
            else:
                rpc.forward(gateway, device, event)
    offline = members(event.channel_id) - set(routes)
    push_service.enqueue(offline, event)  # batched, collapsible
